runs = [
    {"id": 101, "status": "success", "duration_s": 120},
    {"id": 102, "status": "success", "duration_s": 130},
    {"id": 103, "status": "failure", "duration_s": 45},
    {"id": 104, "status": "success", "duration_s": 125},
    {"id": 105, "status": "failure", "duration_s": 50},
]

def success_rate(runs):
    return sum(1 for r in runs if r["status"] == "success") / len(runs)

def average_duration(runs):
    return sum(r["duration_s"] for r in runs) / len(runs)

rate = success_rate(runs)
avg = average_duration(runs)
print(f"tasa de exito: {rate:.0%}")
print(f"duracion media: {avg:.1f}s")

THRESHOLD = 0.9
if rate < THRESHOLD:
    print(f"ALERTA: tasa de exito {rate:.0%} por debajo del umbral {THRESHOLD:.0%}")
else:
    print("sin alerta")
